#include <stdio.h>
#include <math.h>
#include "svpwm_output/svpwm.h"

int main() {
    // Test vectors from test/test_vectors.csv
    struct {
        char id[10];
        float valpha, vbeta;
        uint8_t expected_sector;
        uint16_t exp_cmp_u, exp_cmp_v, exp_cmp_w;
    } tests[] = {
        {"T01", 0.0000f, 0.0000f, 0, 500, 500, 500},
        {"T02", 86.6025f, 50.0000f, 1, 779, 500, 221},
        {"T03", 0.0000f, 100.0000f, 2, 500, 779, 221},
        {"T04", -86.6025f, 50.0000f, 3, 221, 779, 500},
        {"T05", -86.6025f, -50.0000f, 4, 221, 500, 779},
        {"T06", -0.0000f, -100.0000f, 5, 500, 221, 779},
        {"T07", 86.6025f, -50.0000f, 6, 779, 221, 500},
        {"T08", 162.3336f, 0.0000f, 6, 893, 107, 107},
        {"T09", 81.1668f, 140.5850f, 1, 893, 893, 107},
        {"T10", 20.0000f, 10.0000f, 1, 562, 494, 438},
        {"T11", 40.1209f, 69.2121f, 1, 694, 693, 306},
        {"T12", -120.0000f, 40.0000f, 3, 154, 846, 623}
    };

    int num_tests = sizeof(tests) / sizeof(tests[0]);
    int passed = 0;

    printf("Testing SVPWM implementation...\n");
    printf("================================\n");

    for (int i = 0; i < num_tests; i++) {
        SvpwmInput input = {tests[i].valpha, tests[i].vbeta};
        SvpwmOutput output;
        uint8_t sector;

        sector = svpwm_compute(&input, &output);

        int sector_ok = (sector == tests[i].expected_sector);
        int u_ok = (output.cmp_u >= tests[i].exp_cmp_u - 2 && output.cmp_u <= tests[i].exp_cmp_u + 2);
        int v_ok = (output.cmp_v >= tests[i].exp_cmp_v - 2 && output.cmp_v <= tests[i].exp_cmp_v + 2);
        int w_ok = (output.cmp_w >= tests[i].exp_cmp_w - 2 && output.cmp_w <= tests[i].exp_cmp_w + 2);

        int test_passed = sector_ok && u_ok && v_ok && w_ok;
        if (test_passed) passed++;

        printf("%s: Valpha=%7.2f Vbeta=%7.2f | Exp: sector=%d, U=%4d V=%4d W=%4d | ",
               tests[i].id, tests[i].valpha, tests[i].vbeta,
               tests[i].expected_sector, tests[i].exp_cmp_u, tests[i].exp_cmp_v, tests[i].exp_cmp_w);
        printf("Got: sector=%d, U=%4d V=%4d W=%4d | %s\n",
               sector, output.cmp_u, output.cmp_v, output.cmp_w,
               test_passed ? "PASS" : "FAIL");
    }

    printf("================================\n");
    printf("Results: %d/%d tests passed\n", passed, num_tests);

    return (passed == num_tests) ? 0 : 1;
}
